#!/usr/bin/env node
import {parseArgs} from 'node:util';import {readFile} from 'node:fs/promises';import {resolve} from 'node:path';import {pathToFileURL} from 'node:url';import {createD1} from '../tests/helpers/d1-sqlite.mjs';import {handlePrivate} from '../server/private-spc.mjs';import {validateAirTimeline} from '../dist/spc-air.mjs';
const exact=(a,b)=>JSON.stringify(a)===JSON.stringify(b), limit=(dto,v2)=>{const n=dto.timeline.kind.length,bytes=Buffer.byteLength(JSON.stringify(dto));if(n>3000||dto.bpm.changes.length>1000||bytes>(v2?524288:131072))throw Error('limit');if(v2&&(!validateAirTimeline(dto.timeline)||dto.timeline.airVersion!==1))throw Error('air');return bytes};
const request=(url,dto)=>new Request(url+'/api/private-spc/import',{method:'POST',headers:{origin:url,'content-type':'application/json'},body:JSON.stringify(dto)});
async function importAll(charts,d,env,ids,url,expectedStatus){for(const dto of charts){if(!ids.has(dto.chartId))throw Error('catalog');limit(dto,dto.timeline.airVersion===1);d.resetInvocation();const r=await handlePrivate(request(url,dto),env,'local-test-owner',ids);if(r.status!==expectedStatus||d.invocationCount>32)throw Error('import');}}
export async function verify(bundlePath,catalogPath,legacyPath){const bundle=JSON.parse(await readFile(bundlePath,'utf8')),catalog=JSON.parse(await readFile(catalogPath,'utf8')),ids=new Set(catalog.songs.flatMap(s=>s.charts.map(c=>c.chartId))),v2=bundle.format==='infalsus-private-timelines-v2';if(Object.keys(bundle).sort().join(',')!=='charts,format'||bundle.format!==(v2?'infalsus-private-timelines-v2':'infalsus-private-timelines-v1')||!Array.isArray(bundle.charts)||bundle.charts.length!==280)throw Error('bundle');const unique=new Set(bundle.charts.map(x=>x.chartId));if(unique.size!==280)throw Error('duplicate');const notes=bundle.charts.reduce((n,x)=>n+x.timeline.kind.length,0),bytes=bundle.charts.reduce((n,x)=>n+limit(x,v2),0);if(notes!==185068||bytes>20971520||notes>300000)throw Error('coverage');const d=await createD1(),env={DB:d.DB},url='https://site.test';try{if(legacyPath){const legacy=JSON.parse(await readFile(legacyPath,'utf8'));if(legacy.format!=='infalsus-private-timelines-v1'||legacy.charts.length!==280||new Set(legacy.charts.map(x=>x.chartId)).size!==280||legacy.charts.reduce((n,x)=>n+x.timeline.kind.length,0)!==185068)throw Error('legacy');await importAll(legacy.charts,d,env,ids,url,201);const before=await handlePrivate(new Request(url+'/api/private-spc'),env,'local-test-owner',ids),oldRows=(await before.json()).charts;if(oldRows.length!==280)throw Error('legacy-list');const stable=new Map(oldRows.map(x=>[x.chart_id,{id:x.id,created_at:x.created_at}]));d.db.prepare('UPDATE private_spc_rate SET window_start=?,updated_at=? WHERE owner_uid=?').run(Date.now()-60001,Date.now()-60001,'local-test-owner');await importAll(bundle.charts,d,env,ids,url,200);const after=await handlePrivate(new Request(url+'/api/private-spc'),env,'local-test-owner',ids),rows=(await after.json()).charts;if(rows.length!==280)throw Error('upgrade-list');for(const row of rows){const old=stable.get(row.chart_id);if(!old||old.id!==row.id||old.created_at!==row.created_at)throw Error('preserve');}}
else await importAll(bundle.charts,d,env,ids,url,201);
const list=await handlePrivate(new Request(url+'/api/private-spc'),env,'local-test-owner',ids),rows=(await list.json()).charts;if(rows.length!==280||rows.reduce((n,x)=>n+x.note_count,0)!==notes)throw Error('list');for(const row of rows){const r=await handlePrivate(new Request(url+'/api/private-spc/'+row.id),env,'local-test-owner',ids),body=await r.json(),expected=bundle.charts.find(x=>x.chartId===body.payload?.chartId);if(r.status!==200||!exact(body.payload,expected))throw Error('roundtrip');const sizes=d.db.prepare('SELECT length(payload) AS n FROM private_spc_chunk WHERE chart_id=?').all(row.id);if(sizes.some(x=>x.n>65536))throw Error('chunk');d.resetInvocation();const wrong=await handlePrivate(new Request(url+'/api/private-spc/'+row.id),env,'other-local-owner',ids);if(wrong.status!==404||d.invocationCount>32)throw Error('owner');}
d.db.prepare('UPDATE private_spc_rate SET window_start=?,updated_at=? WHERE owner_uid=?').run(Date.now()-60001,Date.now()-60001,'local-test-owner');for(const dto of bundle.charts){d.resetInvocation();const r=await handlePrivate(request(url,dto),env,'local-test-owner',ids);if(r.status!==200||d.invocationCount>32)throw Error('idempotence');}const count=d.db.prepare('SELECT count(*) AS n FROM private_spc WHERE owner_uid=?').get('local-test-owner').n;if(count!==280)throw Error('dedupe');return {charts:rows.length,events:notes,maxCanonicalBytes:Math.max(...bundle.charts.map(x=>Buffer.byteLength(JSON.stringify(x)))),maxNotes:Math.max(...bundle.charts.map(x=>x.timeline.kind.length)),maxBpmChanges:Math.max(...bundle.charts.map(x=>x.bpm.changes.length))}}finally{d.close()}}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href){let v;try{v=parseArgs({options:{bundle:{type:'string'},catalog:{type:'string'},'legacy-bundle':{type:'string'}},strict:true,allowPositionals:false}).values;if(!v.bundle||!v.catalog)throw Error()}catch{console.error('invalid-arguments');process.exit(2)}verify(v.bundle,v.catalog,v['legacy-bundle']).then(x=>console.log(JSON.stringify(x))).catch(()=>{console.error('verification-failed');process.exitCode=1})}
